    "dataSources": {
        "ds_6dsXStlb": {
            "name": "dnsguardai_management_lookup_kvstore_table",
            "options": {
                "query": "| inputlookup anomalous_dns_lookup\n| table domain anomalous_type last_update\n| eval last_update = strftime(last_update, \"%Y-%m-%d %H:%M:%S %Z\")\n| rename anomalous_type as \"Anomalous Type\" domain as Domain last_update as \"Last Update\"",
                "queryParameters": {
                    "earliest": "-24h@h",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        },
        "ds_M4m6Zv7s": {
            "name": "dnsguardai_management_lookup_csv_table",
            "options": {
                "query": "| inputlookup whitelist_domain_lookup\n| rename domain as Domain",
                "queryParameters": {
                    "earliest": "-24h@h",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        },
        "ds_N7Y8pHRC": {
            "name": "dnsguardai_management_savedsearches_table",
            "options": {
                "query": "|rest/servicesNS/-/Splunk-DNS-Guard-AI/saved/searches splunk_server=local\n| search title=\"DNSGuardAI*\" OR title=\"Threat - DNSGuardAI*\"\n| eval is_scheduled = if(is_scheduled=\"1\", \"True\", \"False\")\n| table title description next_scheduled_time is_scheduled cron_schedule\n| rename title as Title description as Description next_scheduled_time as \"Next Scheduled Time\" is_scheduled as \"Is Scheduled\" cron_schedule as \"Cron Schedule\"",
                "queryParameters": {
                    "earliest": "-24h@h",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        }
    },
